option.value:
/* High-Contrast Light Theme with Dark Code Blocks */

/* Main Body Text - Almost Black */
body {
    background-color: #fcfcfc !important;
    color: #0a0a0a !important;
    font-family: sans-serif;
    line-height: 1.6;
}

/* Headings - Bold and Black */
h1, h2, h3, h4, h5, h6 {
    color: #000000 !important;
    font-weight: bold !important;
}

/* Paragraphs and Lists - Strict targeting to avoid breaking syntax spans */
p, li {
    color: #0a0a0a !important;
}

/* Blockquotes */
blockquote {
    border-left: 5px solid #dddddd !important;
    color: #222222 !important;
    padding-left: 15px;
    margin-left: 0;
}

/* Inline Code ONLY - Light gray background, dark red text */
code {
    background-color: #f0f0f0 !important;
    color: #b31010 !important; 
    padding: 2px 5px;
    border-radius: 3px;
    font-family: 'JetBrains Mono', monospace;
}

/* Fenced Code Blocks (Pre) - Dark IDE match */
pre {
    background-color: #1e1f22 !important; /* IntelliJ's default dark background */
    color: #bcbec4 !important;            /* Bright text for standard code */
    padding: 16px !important;
    border-radius: 6px !important;
    overflow: auto !important;
}

/* Protect code blocks from inline code overrides */
pre code {
    background-color: transparent !important;
    color: inherit !important;
    padding: 0 !important;
}

/* Tables */
table, th, td {
    border: 1px solid #bbbbbb !important;
    color: #0a0a0a !important;
    border-collapse: collapse;
}

th {
    background-color: #eeeeee !important;
}
